@use "../base/variables" as *;

.quiz {
    width: 100%;
    max-width: 900px;
    margin: 0 auto;
    padding: 24px 16px 48px;
    box-sizing: border-box;

    &__navigation {
        display: flex;
        align-items: center;
        flex-wrap: wrap;
        gap: 16px;

        h3 {
            font-family: $font-family;
            font-weight: 500;
            color: #d9e0db;
            font-size: 1rem;
        }

        .taskItem {
            cursor: pointer;
            font-family: $font-family;
            font-weight: 700;
            font-size: 0.9rem;
            color: #718078;
            background-color: #1d2721;
            border-radius: 50%;
            padding: 12px 16px;
            min-width: 2.5rem;
            text-align: center;
        }
    }

    &__question {
        margin-top: 24px;

        span {
            display: inline-block;
            color: #d9e0db;
            font-family: $font-family;
            font-weight: 500;
            font-size: clamp(1rem, 2.5vw, 1.25rem);
            background-color: #42584b;
            padding: 12px;
            border-radius: 8px;
            border: solid 2px #1c2721;
            line-height: 1.4;
            max-width: 100%;
        }
    }
}

@media (max-width: 600px) {
    .quiz {
        padding: 16px 12px 40px;

        &__navigation {
            gap: 10px;

            .taskItem {
                padding: 10px 14px;
                font-size: 0.85rem;
            }
        }

        &__question {
            margin-top: 16px;

            span {
                padding: 10px;
            }
        }
    }
}

.statement {
    height: 100vh;
    height: 100dvh;
    width: 100%;
    position: relative;
    overflow: hidden;

    &__progress {
        position: absolute;
        top: 24px;
        left: 50%;
        z-index: 4;
        width: min(500px, calc(100% - 48px));
        transform: translateX(-50%);
        font-family: $font-family;
        color: #d9e0db;
    }

    &__progressHeader {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        margin-bottom: 9px;
        font-size: 0.78rem;
        letter-spacing: 0.04em;
        text-transform: uppercase;

        strong {
            color: #a8c4b1;
            font-weight: 700;
        }
    }

    &__progressTrack {
        height: 7px;
        overflow: hidden;
        border: 1px solid rgba(168, 196, 177, 0.25);
        border-radius: 999px;
        background: rgba(32, 48, 39, 0.82);
        box-shadow: 0 0 18px rgba(122, 154, 130, 0.12);

        span {
            display: block;
            height: 100%;
            border-radius: inherit;
            background: linear-gradient(90deg, #7a9a82, #b8ddc2);
            box-shadow: 0 0 14px rgba(184, 221, 194, 0.5);
            transition: width 0.35s ease;
        }
    }


    &__isCorrect {
        position: absolute;
        left: 50%;
        bottom: 10%;
        z-index: 5;
        display: flex;
        flex-direction: column;
        align-items: center;
        min-width: 180px;
        transform: translate(-50%, 50%);
        border: 1px solid;
        border-radius: 999px;
        overflow: hidden;
        font-family: $font-family;
        font-size: 1rem;
        font-weight: 700;
        letter-spacing: 0.02em;
        box-shadow: 0 12px 30px rgba(0, 0, 0, 0.25);
        animation: statementAnswerIn 0.28s ease-out both;

        &.is-correct {
            color: #E2EEE6;
            border: 1px solid #2e6b4a;
            background: #0f2a1b;
            span{
              background: #2e6b4a;
            }
            .statement__isCorrectTimerBar {
                background: #2e6b4a;
                box-shadow: 0 0 8px rgba(134, 239, 172, 0.7);
            }
        }

        &.is-incorrect {
            color: #E2EEE6;
            border: 1px solid #7a2a2a;
            background: #2a0f0f;
            span{
              background: #7a2a2a;
            }
            .statement__isCorrectTimerBar {
                background: #7a2a2a;
                box-shadow: 0 0 8px rgba(252, 165, 165, 0.7);
            }
        }
    }

    &__isCorrectContent {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 10px;
        padding: 11px 22px 9px;
        width: 100%;
    }

    &__isCorrectTimer {
        position: relative;
        width: 100%;
        height: 3px;
        background: rgba(0, 0, 0, 0.25);
        overflow: hidden;
    }

    &__isCorrectTimerBar {
        display: block;
        height: 100%;
        width: 100%;
        transform-origin: left center;
        animation-name: statementTimerDrain;
        animation-timing-function: linear;
        animation-fill-mode: forwards;
    }

    &__isCorrectIcon {
        display: flex;
        width: 25px;
        height: 25px;
        align-items:center;
        justify-content:center;
        border-radius: 50%;
        font-size: 1rem;
        line-height: 1;
    }
    &__stage {
        position: absolute;
        inset: 0;
        display: flex;
        align-items: center;
        justify-content: center;
        pointer-events: none;
        padding: 24px;
        z-index: 2;
    }

    &__card {
        pointer-events: auto;
        user-select: none;
        position: relative;
        display: flex;
        flex-direction: column;
        gap: 20px;
        border: 3px solid #1b221e;
        border-radius: 1.5rem;
        padding: 56px 40px;
        background-color: #203027;
        width: min(500px, 60%);
        box-shadow: 0 20px 40px 0 rgba(0, 0, 0, 0.25);
        cursor: grab;

        &:active {
            cursor: grabbing;
        }

        p {
            font-family: $font-family;
            font-weight: 600;
            font-size: clamp(0.85rem, 2.5vw, 1.5rem);
            line-height: 140%;
            color: #fff;
        }

        span {
            display: flex;
            font-family: $font-family;
            font-weight: 500;
            font-size: clamp(0.8rem, 2.5vw, 1rem);;
            color: #a1a1aa;
        }
    }



    &__result {
        pointer-events: auto;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 16px;
        text-align: center;
        background-color: #203027;
        border: 3px solid #1b221e;
        border-radius: 1.5rem;
        padding: 48px 40px;
        width: min(420px, 100%);
        box-shadow: 0 20px 40px 0 rgba(0, 0, 0, 0.25);

        h2 {
            font-family: $font-family;
            font-weight: 700;
            font-size: clamp(1.4rem, 3vw, 1.8rem);
            color: #fff;
        }

        p {
            font-family: $font-family;
            font-weight: 500;
            font-size: 1.15rem;
            color: #d9e0db;
        }

        button,
        a {
            font-family: $font-family;
            font-weight: 600;
            font-size: 1rem;
            border-radius: 999px;
            padding: 12px 22px;
            min-width: 160px;
            text-align: center;
        }

        button {
            background: #7a9a82;
            color: #0f1612;
        }

        a {
            color: #a8c4b1;
            border: 1px solid rgba(122, 154, 130, 0.4);
        }
    }

    &__backs {
        display: flex;
        justify-content: space-between;
        user-select: none;
        height: 100%;

        .back {
            position: relative;
            height: 100vh;
            height: 100dvh;
            width: 30%;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 8px;
            overflow: hidden;

            .back__glow {
                position: absolute;
                inset: 0;
                pointer-events: none;
            }

            p {
                position: relative;
                z-index: 1;
                transition: 0.3s;
                font-family: $font-family;
                font-weight: 600;
                font-size: 0.88rem;
                text-transform: uppercase;
                color: #a1a1aa;
            }

            span {
                position: relative;
                z-index: 1;
                font-family: $font-family;
                font-size: 0.75rem;
                color: #718078;
            }
        }

        .leftBack {
            border-right: solid 2px #1b221e;

            .back__glow {
                background-color: rgba(239, 68, 68, 0.14);
            }

            &:hover p,
            &:focus-visible p {
                color: rgb(252, 165, 165);
            }
        }

        .rightBack {
            border-left: solid 2px #1b221e;

            .back__glow {
                background-color: rgba(34, 197, 94, 0.14);
            }

            &:hover p,
            &:focus-visible p {
                color: rgb(134, 239, 172);
            }
        }
    }
}

@keyframes statementAnswerIn {
    from {
        opacity: 0;
        transform: translate(-50%, 75%) scale(0.92);
    }

    to {
        opacity: 1;
        transform: translate(-50%, 50%) scale(1);
    }
}

@keyframes statementTimerDrain {
    from {
        transform: scaleX(1);
    }

    to {
        transform: scaleX(0);
    }
}
@media (max-width: 768px) {
    .statement {
        &__progress {
            top: 16px;
            width: calc(100% - 32px);
        }

        &__progressHeader {
            font-size: 0.68rem;
        }

        &__backs .back {
            width: 22%;

            span {
                display: none;
            }
        }

        &__isCorrect {
            bottom: 8%;
            min-width: 158px;
            padding: 11px 17px;
            font-size: 0.9rem;
        }

        &__card {
            padding: 40px 24px;
        }

        &__result {
            padding: 36px 24px;
        }
    }
}
